`timescale 1ns/1ps
// Conformance testbench: feeds a byte corpus (generated by tools/conformance.py) into
// host_frame_rx and prints exactly what it decoded, so the Python side can diff it
// against its own parser (tools/conformance.py --check).
//
// Output format (one line per frame, payload as uppercase hex or "-"):
//     FRAME <TT> <LEN> <PAYLOAD>
//     STATS good=<n> crc=<n> len=<n> tail=<n>
module tb_conformance;
    localparam integer MAX_WORDS = 4096;

    reg clk = 0;
    always #10 clk = ~clk;
    reg rst_n = 0;

    reg [7:0]  corpus [0:MAX_WORDS-1];
    integer    n_words = 0;
    integer    n_bytes = 0;

    reg  [7:0] byte_in = 8'h00;
    reg        byte_valid = 1'b0;
    wire       frame_valid;
    wire [7:0] frame_type, frame_len;
    wire [63:0] payload_head;
    wire [15:0] good_cnt, crc_cnt, len_cnt, tail_cnt, sync_cnt, timeout_cnt;

    host_frame_rx #(
        .MAX_LEN(32),
        .TIMEOUT_CYCLES(20000),
        .CNT_W(16)
    ) u_dut (
        .clk(clk), .rst_n(rst_n),
        .byte_in(byte_in), .byte_valid(byte_valid),
        .frame_valid(frame_valid), .frame_type(frame_type),
        .frame_len(frame_len), .payload_head(payload_head),
        .good_cnt(good_cnt), .crc_err_cnt(crc_cnt), .len_err_cnt(len_cnt),
        .tail_err_cnt(tail_cnt), .sync_err_cnt(sync_cnt), .timeout_cnt(timeout_cnt)
    );

    integer i, j;
    reg [7:0] b;
    integer   fd;
    reg       done = 0;

    // read the corpus: file has hex bytes separated by spaces/newlines
    task automatic load_corpus(input [1023:0] path);
        integer fd;
        integer rc;
        begin
            n_words = 0;
            n_bytes = 0;
            fd = $fopen(path, "r");
            if (fd == 0) begin
                $display("FAIL cannot open %0s", path);
                $fatal(1);
            end
            while (!$feof(fd) && n_words < MAX_WORDS) begin
                rc = $fscanf(fd, "%h", b);
                if (rc == 1) begin
                    corpus[n_words] = b;
                    n_words = n_words + 1;
                end else begin
                    rc = $fgetc(fd);   // skip separators
                    if (rc < 0) break;
                end
            end
            $fclose(fd);
            n_bytes = n_words;
            $display("loaded %0d bytes", n_bytes);
        end
    endtask

    initial begin
        load_corpus("sim/vectors/conformance.hex");
        repeat (10) @(posedge clk);
        rst_n = 1;
        repeat (10) @(posedge clk);

        // feed one byte every 4 clocks
        for (i = 0; i < n_bytes; i = i + 1) begin
            @(negedge clk);
            byte_in    = corpus[i];
            byte_valid = 1'b1;
            @(negedge clk);
            byte_valid = 1'b0;
            repeat (3) @(negedge clk);
        end

        // give the parser time for the inter-byte timeout on the trailing truncation
        repeat (30000) @(negedge clk);

        $display("STATS good=%0d crc=%0d len=%0d tail=%0d",
                 good_cnt, crc_cnt, len_cnt, tail_cnt);
        $finish;
    end

    // print every accepted frame (payload capped at the 8 bytes the RTL stores)
    always @(posedge clk) begin
        if (frame_valid) begin
            $write("FRAME %02X %0d ", frame_type, frame_len);
            for (j = 0; j < frame_len && j < 8; j = j + 1) begin
                b = payload_head[j*8 +: 8];
                $write("%02X", b);
            end
            if (frame_len == 0) $write("-");
            if (frame_len > 8)  $write(" TRUNC");
            $write("\n");
        end
    end

    initial begin
        #50_000_000;
        $display("FAIL tb_conformance timeout");
        $finish;
    end
endmodule
